function overlayTrees(a: TreeNode | null, b: TreeNode | null): TreeNode | null {
  if (!a) return b;
  if (!b) return a;
  const node = new TreeNode(a.val + b.val);
  node.left = overlayTrees(a.left, b.left);
  node.right = overlayTrees(a.right, b.right);
  return node;
}

