function overlayTrees(a: TreeNode | null, b: TreeNode | null): TreeNode | null {
  if (!a) return b;
  const stack: [TreeNode, TreeNode | null][] = [[a, b]];
  while (stack.length) {
    const [x, y] = stack.pop()!;
    if (!y) continue;
    x.val += y.val;
    if (!x.left) x.left = y.left;
    else stack.push([x.left, y.left]);
    if (!x.right) x.right = y.right;
    else stack.push([x.right, y.right]);
  }
  return a;
}

